insert into public.repositories (github_id, owner, name, full_name, slug, github_url, homepage_url, description, summary, kind, primary_language, license_key, topics, stars, forks, open_issues, avatar_url, is_archived, created_at_github, updated_at_github, last_pushed_at, stats_checked_at, published_at, status, difficulty, featured) select github_id, owner, name, full_name, slug, github_url, homepage_url, description, summary, kind, primary_language, license_key, topics, stars, forks, open_issues, avatar_url, is_archived, created_at_github, updated_at_github, last_pushed_at, stats_checked_at, published_at, status, difficulty, featured from seed_repos on conflict (github_id) do update set owner = excluded.owner, name = excluded.name, full_name = excluded.full_name, slug = excluded.slug, github_url = excluded.github_url, homepage_url = excluded.homepage_url, description = excluded.description, summary = excluded.summary, kind = excluded.kind, primary_language = excluded.primary_language, license_key = excluded.license_key, topics = excluded.topics, stars = excluded.stars, forks = excluded.forks, open_issues = excluded.open_issues, avatar_url = excluded.avatar_url, is_archived = excluded.is_archived, created_at_github = excluded.created_at_github, updated_at_github = excluded.updated_at_github, last_pushed_at = excluded.last_pushed_at, stats_checked_at = excluded.stats_checked_at, published_at = excluded.published_at, status = excluded.status, difficulty = excluded.difficulty, featured = excluded.featured;
insert into public.repository_categories (repository_id, category_id, is_primary) select r.id, c.id, x.ord = 1 from seed_repos s cross join lateral unnest(s.categories) with ordinality as x(slug, ord) join public.repositories r on r.github_id = s.github_id join public.categories c on c.slug = x.slug on conflict (repository_id, category_id) do update set is_primary = excluded.is_primary;
insert into public.repository_stats (repository_id, recorded_at, recorded_on, stars, forks, open_issues) select r.id, s.stats_checked_at, (s.stats_checked_at at time zone 'utc')::date, s.stars, s.forks, s.open_issues from seed_repos s join public.repositories r on r.github_id = s.github_id on conflict (repository_id, recorded_on) do nothing;
insert into public.repository_content (repository_id, sixty_seconds, features, strengths, limitations, use_cases, costs, troubleshooting, source_urls, source_commit_sha, last_reviewed_at, hero_commands, overview, best_for, facts, install_meta) values ((select id from public.repositories where slug = 'openseo'), '{"whatItDoes":"OpenSEO is a command-line tool that crawls a website, runs rule-based SEO checks on the HTML (titles, images, links and more), and asks a language model of your choice to turn the findings into recommendations.","problem":"AI-assisted SEO tools are usually hosted services tied to one AI vendor. OpenSEO runs on your own machine and lets you switch providers, including fully local models through Ollama.","whoFor":["Developers who want SEO audits they can script from the terminal","Marketers and SEO professionals comfortable with a command line","Teams that need to pick their own LLM provider or keep data local","Engineers who want to catch SEO regressions between deploys"],"whyChoose":"Choose it if you want an open-source, scriptable audit where you control the model and your data. If you want a hosted dashboard with no setup, this isn''t that.","requirements":["Python 3.11 or newer","Git, to install from source","An API key for a hosted LLM provider, or Ollama running locally","Optional: Playwright Chromium for JavaScript-rendered sites"]}'::jsonb, '[{"icon":"scan-search","title":"Full SEO audit","body":"Rules-based HTML checks plus LLM-written recommendations, with optional sitemap-only crawling and a PDF report."},{"icon":"layers","title":"Any LLM provider","body":"Switch between OpenAI, Claude, Gemini, Groq, Ollama and more with one command, via LiteLLM."},{"icon":"shield","title":"Local and private","body":"Point it at a local Ollama model and audits run without sending pages to a hosted AI service."},{"icon":"file-code","title":"Editable prompts","body":"Prompts live as Markdown templates, not hardcoded strings, so you can tune them for your niche."},{"icon":"git-compare","title":"SEO drift checks","body":"Capture a baseline and compare later to catch lost canonicals, noindex changes or missing schema."},{"icon":"puzzle","title":"Plugins and caching","body":"Plugin architecture for custom commands and providers; SQLite cache with configurable TTL."}]'::jsonb, array['Not locked to one AI vendor, and works with free local models', 'Readable, editable prompts make the AI part transparent', 'Covers more than audits: content, schema, drift, sitemap and robots.txt checks', 'MIT licensed, so it''s fine for commercial use']::text[], array['Early stage: version 0.1.0, marked "Alpha" in its package metadata', 'Not on PyPI when we checked (Nov 24, 2026), even though the README shows pip install openseo. Install from source instead', 'Small community so far (5 stars, 3 forks on Nov 24, 2026), so fewer answers exist online', 'Pins LiteLLM 1.40.0, so give it its own virtual environment', 'Recommendation quality depends on the model you choose; hosted models cost money per request']::text[], '[{"title":"Pre-launch audit","body":"Crawl a staging site, review issues in the terminal and hand the PDF report to your team."},{"title":"Content optimization","body":"Run seo content with a target keyword to find gaps in a blog post."},{"title":"Structured data","body":"Generate Schema.org JSON-LD for an article or profile page with seo schema."},{"title":"Regression guard","body":"Take a drift baseline of key pages, then compare after each deploy."}]'::jsonb, '[{"label":"License","value":"MIT. Free to use, modify and use commercially.","tone":"free"},{"label":"Software","value":"Free and open source. Runs on your machine, so there''s nothing to host.","tone":"free"},{"label":"Hosted AI providers","value":"Billed per token by your provider (OpenAI, Anthropic, Google…). Cost grows with pages audited and model size.","tone":"paid"},{"label":"Local models","value":"No API fees with Ollama, but you need hardware that can run your chosen model.","tone":"depends"},{"label":"Optional extras","value":"Playwright Chromium for JavaScript rendering is free to download.","tone":"free"}]'::jsonb, '[{"problem":"pip install openseo can''t find the package","solution":"OpenSEO wasn''t published on PyPI when we checked (Nov 24, 2026). Install from source with pip install -e . as shown above."},{"problem":"The seo command is missing or runs old code","solution":"Activate your virtual environment and install in editable mode (pip install -e .) so the seo command points at the source you cloned.","sourceUrl":"https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/HOW_TO_USE.md"},{"problem":"API key or connection problems","solution":"Run seo doctor. It checks API keys, the cache database, Playwright and internet connectivity.","sourceUrl":"https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/HOW_TO_USE.md"},{"problem":"Audits with Ollama fail","solution":"Make sure Ollama is running (ollama list) and that you pulled the model first, for example ollama pull llama3.1.","sourceUrl":"https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/README.md"},{"problem":"Content on JavaScript-heavy sites is missing","solution":"Install the extras and Chromium: pip install -e \".[all]\" then playwright install chromium.","sourceUrl":"https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/README.md"}]'::jsonb, array['https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/README.md', 'https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/HOW_TO_USE.md', 'https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/pyproject.toml']::text[], '7ea75c74b3c1d1e804957fa516f323ab5bb71998', '2026-11-24', '[{"comment":"Set up your default provider","command":"seo init"},{"comment":"Check keys, cache and connectivity","command":"seo doctor"},{"comment":"Audit a site and save a PDF report","command":"seo audit https://example.com --report"}]'::jsonb, array['OpenSEO combines two kinds of checks. Rule-based analyzers parse each crawled page for technical issues, then an LLM reviews the results and writes recommendations. Prompts are plain Markdown templates in the repository, so you can read and edit exactly what the model is asked.', 'Model access goes through LiteLLM, which is why one interface works with OpenAI, Anthropic Claude, Google Gemini, Groq, DeepSeek, Together AI, Fireworks, Ollama and other OpenAI-compatible endpoints. Responses are cached locally in SQLite so repeated audits don''t repeat API calls.', 'Beyond the main audit, the CLI includes content analysis against a target keyword, Schema.org JSON-LD generation, sitemap and robots.txt checks, keyword clustering, PDF reports, and "drift" snapshots that compare a page''s SEO-relevant structure before and after a deploy.']::text[], array['Developers who want SEO audits in the terminal or CI scripts', 'SEO professionals who want AI recommendations without vendor lock-in', 'Privacy-conscious teams running local models']::text[], '[{"label":"Type","value":"CLI tool"},{"label":"Language","value":"Python 3.11+"},{"label":"License","value":"MIT"},{"label":"Setup","value":"Intermediate"},{"label":"Version","value":"0.1.0 (Alpha)"}]'::jsonb, '{"verificationNote":"Commands come from OpenSEO''s README and HOW_TO_USE guide. AIRepoHub hasn''t run them yet.","supportedOs":["Windows","macOS","Linux"],"firstRun":[{"title":"Initialize configuration","body":"Interactive wizard for your default provider and settings.","code":"seo init","lang":"bash"},{"title":"Add an API key (skip if using Ollama)","code":"export OPENAI_API_KEY=\"sk-...\"","lang":"bash"},{"title":"Verify the installation","code":"seo doctor","lang":"bash"},{"title":"Run your first audit","code":"seo audit https://example.com","lang":"bash"}],"sourceUrl":"https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/README.md"}'::jsonb) on conflict (repository_id) do update set sixty_seconds = excluded.sixty_seconds, features = excluded.features, strengths = excluded.strengths, limitations = excluded.limitations, use_cases = excluded.use_cases, costs = excluded.costs, troubleshooting = excluded.troubleshooting, source_urls = excluded.source_urls, source_commit_sha = excluded.source_commit_sha, last_reviewed_at = excluded.last_reviewed_at, hero_commands = excluded.hero_commands, overview = excluded.overview, best_for = excluded.best_for, facts = excluded.facts, install_meta = excluded.install_meta;
insert into public.installation_guides (repository_id, operating_system, method, label, sort_order, prerequisites, instructions, environment, expected_output, verification_status, source_url, source_commit_sha, last_reviewed_at, status) values ((select id from public.repositories where slug = 'openseo'), 'macos'::os_target, 'source', 'macOS', 0, '["Python 3.11+","pip","Git"]'::jsonb, '[{"title":"Clone the repository","body":"The README''s clone URL points to github.com/openseo/openseo. This uses the repository''s actual location.","code":"git clone https://github.com/vikasswebdev/OpenSEO.git\ncd OpenSEO","lang":"bash"},{"title":"Create and activate a virtual environment","code":"python -m venv .venv\nsource .venv/bin/activate","lang":"bash"},{"title":"Install OpenSEO in editable mode","body":"Core install. Add the [all] extra and Playwright''s Chromium only if you need JavaScript rendering.","code":"pip install -e .\n\n# Optional: JavaScript rendering and dev tools\npip install -e \".[all]\"\nplaywright install chromium","lang":"bash"}]'::jsonb, '[{"name":"OPENAI_API_KEY","required":false,"description":"Needed only when using OpenAI. The README recommends environment variables for keys."},{"name":"seo provider set-key <provider> <key>","required":false,"description":"Alternative: store a key for any provider (anthropic, gemini, groq…) in OpenSEO''s config."},{"name":"~/.openseo/config.json","required":false,"description":"Created by seo init. Holds your default provider, model, cache and output settings."}]'::jsonb, null, 'official_docs'::verification_status, 'https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/README.md', '7ea75c74b3c1d1e804957fa516f323ab5bb71998', '2026-11-24', 'published'::content_status) on conflict (repository_id, operating_system, method) do update set label = excluded.label, sort_order = excluded.sort_order, prerequisites = excluded.prerequisites, instructions = excluded.instructions, environment = excluded.environment, expected_output = excluded.expected_output, verification_status = excluded.verification_status, source_url = excluded.source_url, source_commit_sha = excluded.source_commit_sha, last_reviewed_at = excluded.last_reviewed_at, status = excluded.status;
