insert into public.tutorials (repository_id, title, slug, content, status, source_url) values ((select id from public.repositories where slug = 'openseo'), 'Run a private SEO audit with a local model', 'run-a-private-seo-audit-with-a-local-model', '{"useCase":"Audit your website with a model running on your own computer, so no page content goes to a hosted AI provider and there are no API fees.","setup":["OpenSEO installed (see Installation)","Ollama installed and running","Enough memory and disk for the model you pull (see Ollama''s docs)"],"steps":[{"title":"Check that Ollama is running","code":"ollama list","lang":"bash"},{"title":"Download a model","code":"ollama pull llama3.1","lang":"bash"},{"title":"Point OpenSEO at it","code":"seo provider use ollama --model ollama/llama3.1","lang":"bash"},{"title":"Audit your site and generate a report","code":"seo audit https://your-site.com --report","lang":"bash"}],"expected":"OpenSEO crawls the site, runs its rule-based checks and adds AI recommendations from the local model. With --report it saves a page-by-page PDF (scorecards, consolidated issues and an AI roadmap) in a results/ folder.","nextSteps":["Audit every sitemap URL: seo audit https://your-site.com --sitemap-only --max-pages 0","Check a post against a keyword: seo content <url> --keyword \"your keyword\"","Save a drift baseline before your next deploy: seo drift baseline <url>"]}'::jsonb, 'published', 'https://github.com/vikasswebdev/OpenSEO/blob/7ea75c74b3c1d1e804957fa516f323ab5bb71998/README.md') on conflict (repository_id, slug) do update set title = excluded.title, content = excluded.content, status = excluded.status, source_url = excluded.source_url;
